const BrassStartTemplate& tromboneStart(int reg, int dynamic) {
	reg = reg < 0 ? 0 : reg > 2 ? 2 : reg;
	dynamic = dynamic < 0 ? 0 : dynamic > 2 ? 2 : dynamic;
	// Where the recordings gave no start for this register and dynamic, the same register's at the nearest
	// dynamic — ff before pp for mf — then the next register's: how fast a start opens up depends far more on
	// the register than on the dynamic (C3 to C5 at mf and ff alike are still 5 dB short at 90 ms, E2 to B2
	// at ff 2), so the low register's mf, which the recordings lack, was judged too slow by the middle's.
	if (STARTS[reg][dynamic].count > 0)
		return STARTS[reg][dynamic];
	for (int d : {dynamic + 1, dynamic - 1, dynamic + 2, dynamic - 2})
		if (d >= 0 && d < 3 && STARTS[reg][d].count > 0)
			return STARTS[reg][d];
	for (int r : {reg + 1, reg - 1, reg + 2, reg - 2})
		if (r >= 0 && r < 3 && STARTS[r][dynamic].count > 0)
			return STARTS[r][dynamic];
	return STARTS[1][1];
}


